window.MOTIF_CATALOG_CHUNKS[69]={"cards":[{"id":"MEJE-KW-007016","row_version":3,"title":"모든 일을 환상으로 돌리는 해석","original":"Delusion Conclusion","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"관객이 작품 속 비현실적 사건을 실제 사건이 아니라 꿈이나 환각이었다고 해석한다. 작품의 세계관을 인정하기보다 현실적인 틀에 맞추려는 수용 방식이다. 특별한 경험을 실제가 아니었다고 여기는 해석은 인물 내부에서는 지난 영광을 꿈으로 치부하기으로 나타난다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-007016/index.html"},{"id":"MEJE-KW-007017","row_version":2,"title":"스스로를 미인이라 믿는 인물","original":"Delusions of Beauty","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 다른 사람들의 반응과 관계없이 자신의 외모가 누구보다 뛰어나다고 확신한다. 자기 평가와 주변의 평가가 어긋나 희극적 상황이 생긴다. 자기 평가가 주변의 평가와 다른 인물상이라는 점에서 인기를 착각하는 인물과 짝을 이룬다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007017/index.html"},{"id":"MEJE-KW-007018","row_version":1,"title":"자신을 동물이라 믿는 인물","original":"Delusions of Doghood","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사람인 인물이 몸이 실제로 변하지 않았는데도 자신을 개나 다른 동물이라고 믿고 행동한다. 실제 변신과 착각을 구분하는 인물 설정이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007018/index.html"},{"id":"MEJE-KW-007019","row_version":1,"title":"말을 잘한다고 착각하는 장황한 화법","original":"Delusions of Eloquence","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"세련되게 말하려는 인물이 어려운 단어와 격식을 지나치게 쓰다가 어색하거나 틀린 표현을 만든다. 스스로 생각하는 언변과 듣는 이가 느끼는 말투가 다르다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007019/index.html"},{"id":"MEJE-KW-007020","row_version":3,"title":"일방적인 친구 관계","original":"Delusions of Friendship","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물은 상대를 친한 친구라고 믿지만 다른 쪽은 같은 친밀감을 느끼지 않는다. 서로 다른 관계 인식이 이용이나 실망으로 이어진다. 가까운 사람의 감정을 자기 바람에 맞춰 오해한다는 점에서 부모의 사랑을 오해하는 자녀과 연결된다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007020/index.html"},{"id":"MEJE-KW-007021","row_version":2,"title":"지역 방송인의 과장된 명성 의식","original":"Delusions of Local Grandeur","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"지역 방송인이 화면에 자주 나온다는 이유로 자신의 영향력과 대중의 관심을 지나치게 크게 여긴다. 매체 노출과 실제 명성을 혼동하는 인물상이다. 매체에 얼굴을 비춘 사실을 실제 인기와 혼동하면 인기를 착각하는 인물의 변형이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007021/index.html"},{"id":"MEJE-KW-007022","row_version":1,"title":"부모의 사랑을 오해하는 자녀","original":"Delusions of Parental Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"부모의 냉대나 학대에도 자녀가 자신은 사랑받고 있다고 굳게 믿는다. 관계를 있는 그대로 보기 어려운 마음이 인물의 상처를 드러낸다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-007022/index.html"},{"id":"MEJE-KW-007023","row_version":1,"title":"인기를 착각하는 인물","original":"Delusions of Popularity","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"주변의 무관심이나 반감에도 자신이 모두에게 사랑받는다고 믿는 인물이다. 자기 인식과 사회적 반응의 차이가 희극이나 갈등을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007023/index.html"},{"id":"MEJE-KW-007024","row_version":1,"title":"머리를 가져오라는 명령","original":"Demanding Their Head","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"권력자가 적을 죽이는 데 그치지 않고 그 머리를 증거처럼 가져오라고 요구한다. 분노와 지배력을 과시하는 명령이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007024/index.html"},{"id":"MEJE-KW-007025","row_version":1,"title":"수요 폭주","original":"Demand Overload","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"새 작품이나 서비스에 예상보다 많은 사람이 몰려 접속이 마비되거나 물건이 순식간에 동난다. 관심의 크기가 공급 능력을 넘어서는 현상이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007025/index.html"},{"id":"MEJE-KW-007026","row_version":2,"title":"움직이는 해골","original":"Dem Bones","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"뼈만 남은 몸이 스스로 움직이는 언데드 존재다. 생명 활동을 지탱할 살과 근육이 없다는 점 자체가 기이함을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007026/index.html"},{"id":"MEJE-KW-007027","row_version":1,"title":"인간과 닮은 이종족","original":"Demihuman","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"기본적인 몸의 구조는 인간과 비슷하지만 특징적인 외형이나 능력으로 구별되는 환상 종족이다. 익숙한 인간상과 낯선 존재의 차이를 함께 지닌다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007027/index.html"},{"id":"MEJE-KW-007028","row_version":2,"title":"최고신을 사칭하는 창조신","original":"Demiurge Archetype","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"세계나 인류를 실제로 창조했을 수 있지만 참된 최고신인 척 군림하는 존재. 자신의 제한된 권위를 절대적인 것으로 내세우는 악역 유형. 작품 속 신격의 기원을 따질 때 필멸자가 만들어 낸 신은 창조신의 권위가 어디서 왔는지 다른 답을 준다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007028/index.html"},{"id":"MEJE-KW-007029","row_version":1,"title":"체험판 이용 보너스","original":"Demo Bonus","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 체험판을 해 본 사람에게 정식판에서 진행 기록이나 특별한 이득을 제공한다. 체험판의 플레이가 정식 게임의 시작에 영향을 준다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-007029/index.html"},{"id":"MEJE-KW-007030","row_version":2,"title":"민주주의를 악으로 그리기","original":"Democracy Is Bad","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품이 민주주의를 부패와 선동, 다수의 횡포를 낳는 위험한 체제로 묘사한다. 정치 체제에 대한 작품 속 평가를 나타내며 현실의 보편적 사실로 단정하지 않는다. 체제의 약점을 지적하되 완전히 부정하지 않는 관점은 불완전한 민주주의으로 구분한다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-007030/index.html"},{"id":"MEJE-KW-007031","row_version":1,"title":"불완전한 민주주의","original":"Democracy Is Flawed","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품이 민주주의의 약점과 실패를 인정하면서도 그 체제를 완전히 부정하지는 않는다. 견제와 개선의 필요를 함께 제기하는 정치적 관점이다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-007031/index.html"},{"id":"MEJE-KW-007032","row_version":2,"title":"대상 연령을 넘나드는 유머","original":"Demographically Inappropriate Humour","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"어린이를 주 대상으로 한 작품에 성인이 알아들을 암시나 농담을 넣는다. 관객의 연령에 따라 같은 장면에서 받아들이는 뜻이 달라진다. 서로 다른 관객의 기대가 한 작품에서 충돌한다는 점에서 대상 연령이 어긋나는 합동 출연과 닿는다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-007032/index.html"},{"id":"MEJE-KW-007033","row_version":1,"title":"대상 연령이 어긋나는 합동 출연","original":"Demographic-Dissonant Crossover","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"성인용 작품의 인물과 가족용 작품의 인물이 한 이야기에서 만난다. 서로 다른 표현 수위와 관객 기대를 어떻게 맞출지가 관건이 된다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-007033/index.html"},{"id":"MEJE-KW-007034","row_version":2,"title":"관객층의 인구통계 분류","original":"Demographics","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"방송과 광고가 관객을 나이, 성별, 지역 등 통계적 특성에 따라 나누어 파악한다. 작품의 편성과 판매 전략에 영향을 주는 산업적 분류다. 관객층을 나누는 기준을 이해하면 대상 연령을 넘나드는 유머이 겨냥하는 이중 관객도 보인다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-007034/index.html"},{"id":"MEJE-KW-007035","row_version":2,"title":"폭발물 전문가","original":"Demolitions Expert","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"팀에서 폭발물과 관련된 위기나 임무를 담당하는 전문 인물이다. 기술적 숙련이 문제 해결의 핵심 자원으로 배치된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007035/index.html"},{"id":"MEJE-KW-007036","row_version":2,"title":"악마와 마귀를 구분하는 세계","original":"Demon/Devil Distinction","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품의 설정에서 비슷하게 보이는 악마와 마귀를 별개 종족이나 계급으로 나눈다. 서로 다른 기원과 규칙이 초자연 세계의 질서를 만든다. 악마와 다른 종족의 경계를 정하는 설정은 악마와 연결된 흡혈귀의 성립에도 영향을 준다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-007036/index.html"},{"id":"MEJE-KW-007037","row_version":2,"title":"악마처럼 커지는 분노의 얼굴","original":"Demon Head","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"분노한 인물의 얼굴이 순간적으로 거대한 악마 형상처럼 과장된다. 실제 변신보다 감정의 세기를 시각적으로 전달하는 연출이다. 머리의 비정상적인 움직임으로 감정이나 공포를 전달한다는 점에서 악마 같은 고개 떨림과 비교된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007037/index.html"},{"id":"MEJE-KW-007038","row_version":1,"title":"이형의 악마 괴물","original":"Demonic Abomination","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"인간이나 익숙한 동물과 닮지 않은 낯선 형상의 악마가 등장한다. 형태를 쉽게 분류할 수 없다는 점이 초자연적 공포를 더한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007038/index.html"},{"id":"MEJE-KW-007039","row_version":1,"title":"악마 같은 복화술 인형","original":"Demonic Dummy","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"복화술 인형이 단순한 소품을 넘어 스스로 움직이거나 주인을 지배하는 위협으로 등장한다. 사람을 닮은 물건의 불안함을 활용한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-007039/index.html"},{"id":"MEJE-KW-007040","row_version":2,"title":"악마 같은 고개 떨림","original":"Demonic Head Shake","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"몸은 멈춘 채 머리만 비정상적으로 빠르게 흔들려 존재의 기이함을 보여 주는 영상 효과다. 움직임의 부자연스러움이 공포를 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007040/index.html"},{"id":"MEJE-KW-007041","row_version":2,"title":"악마의 빙의","original":"Demonic Possession","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"악마나 악령이 다른 존재의 몸을 점유해 말과 행동을 지배한다. 겉모습은 같아도 의식의 주인이 달라지는 초자연적 설정이다. 인간의 몸을 악마가 점유하는 경우와 인간 자체가 인간에서 악마가 된 존재이 되는 경우는 서로 다른 변형이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-007041/index.html"},{"id":"MEJE-KW-007042","row_version":1,"title":"일반 적인데 지나치게 강한 적","original":"Demonic Spiders","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"보스가 아닌 흔한 적이 동급의 일반 적보다 훨씬 위험해 플레이어가 마주칠 때마다 긴장한다. 반복 등장한다는 점이 어려움을 더한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-007042/index.html"},{"id":"MEJE-KW-007043","row_version":2,"title":"악마와 연결된 흡혈귀","original":"Demonic Vampires","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"흡혈귀의 기원이나 힘을 악마와 이어 붙이는 설정이다. 피를 마시는 존재와 지옥의 존재가 같은 초자연 계보에 놓인다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007043/index.html"},{"id":"MEJE-KW-007044","row_version":1,"title":"상대를 악마로 몰아가기","original":"Demonization","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"대상에 관한 사실을 왜곡하거나 지어내어 본질적으로 사악한 존재처럼 보이게 한다. 근거보다 공포와 혐오를 앞세우는 묘사나 주장이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007044/index.html"},{"id":"MEJE-KW-007045","row_version":2,"title":"마왕으로 그려지는 오다 노부나가","original":"Demon King Nobunaga","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"일본 전국시대의 오다 노부나가를 문자 그대로 초자연적 마왕처럼 재해석하는 관습이다. 역사 인물에게 붙은 별칭이 환상 서사의 정체성으로 확대된다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007045/index.html"},{"id":"MEJE-KW-007046","row_version":1,"title":"악마 군주의 서열","original":"Demon Lords and Archdevils","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"최상위 악마 아래 여러 군주와 대공이 각자의 영역이나 군단을 거느린다. 지옥을 단일한 무리보다 권력 관계가 있는 사회로 그린다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-007046/index.html"},{"id":"MEJE-KW-007047","row_version":1,"title":"인간에서 악마가 된 존재","original":"Demon of Human Origin","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"원래 인간이었던 영혼이나 인물이 죽음과 저주 등의 과정을 거쳐 악마가 된다. 인간성과 괴물성의 경계를 한 인물의 변화로 보여 준다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007047/index.html"},{"id":"MEJE-KW-007048","row_version":1,"title":"악마 사냥꾼","original":"Demon Slaying","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"악마의 위협에 맞서 추적과 퇴치를 맡는 인물 유형이다. 인간보다 강한 적을 상대하는 숙련과 결심이 역할을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007048/index.html"},{"id":"MEJE-KW-007049","row_version":1,"title":"악마의 힘을 쓰는 마법사","original":"Demon Sorcerer","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"계약, 혈통, 변신, 소환 등으로 악마와 연결된 힘을 다루는 마법사다. 힘의 출처가 인물의 능력과 정체성을 함께 규정한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007049/index.html"},{"id":"MEJE-KW-007050","row_version":1,"title":"결말에서 원래 모습으로 돌아오기","original":"Demorphing Denouement","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"변신하거나 변화한 인물이 이야기의 마지막에 본래의 모습이나 상태를 되찾는다. 원상회복을 결말의 정서적 해소와 연결한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007050/index.html"},{"id":"MEJE-KW-007051","row_version":1,"title":"지난 영광을 꿈으로 치부하기","original":"Demoted Memories","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 과거의 특별한 경험을 기억하면서도 그것이 실제였음을 믿지 않으려 한다. 한때의 정체성을 잊거나 부정해 현재의 평범한 삶을 유지한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007051/index.html"},{"id":"MEJE-KW-007052","row_version":2,"title":"웃음거리로 격하된 중요 인물","original":"Demoted to Comic Relief","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"한때 큰 비중이나 위협을 지녔던 인물이 뒤의 이야기에서는 주로 농담을 위한 역할만 맡는다. 인물의 서사적 위상이 달라졌음을 보여 준다. 예전의 위협적인 인물이 새 이야기에서 낮은 위치로 옮겨지는 다른 방식은 새 악당의 부하가 된 옛 최종 악당이다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007052/index.html"},{"id":"MEJE-KW-007053","row_version":1,"title":"새 악당의 부하가 된 옛 최종 악당","original":"Demoted to Dragon","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"이전 이야기의 최종 악당이 더 강한 새 악당의 지휘 아래 들어간다. 남아 있는 인물의 위상 변화로 적대 세력의 규모를 보여 준다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007053/index.html"},{"id":"MEJE-KW-007054","row_version":2,"title":"주연에서 단역으로 밀린 인물","original":"Demoted to Extra","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"후속편이나 새 시즌에서 주요 인물이 등장만 할 뿐 이야기에서 맡는 일이 크게 줄어드는 현상. 이전의 비중을 기억하는 관객에게 변화가 두드러진다. 중요하던 인물이 연애 상대의 보조 역할로 밀려난 경우 연애 상대 역할로 축소된 인물이 구체적인 양상이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007054/index.html"},{"id":"MEJE-KW-007055","row_version":2,"title":"연애 상대 역할로 축소된 인물","original":"Demoted to Satellite Love Interest","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"독자적인 목표와 역할이 있던 인물이 연애 관계에 들어간 뒤 상대 주인공을 돕는 기능으로만 쓰이는 구성. 관계가 인물 고유의 서사를 밀어낸다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007055/index.html"},{"id":"MEJE-KW-007056","row_version":2,"title":"신화의 현실적 재해석","original":"Demythification","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"신화나 전설을 새로 만들면서 신과 마법을 제거하거나 모호하게 돌려 사건을 현실적인 역사처럼 설명하는 각색 방식. 초자연적 요소 대신 인간의 행동을 중심에 놓는다. 전설을 다시 해석한 작품이 처음에는 원본을 따르다 고유한 방향을 찾으면 모방작의 차별화가 나타난다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007056/index.html"},{"id":"MEJE-KW-007057","row_version":2,"title":"동물임을 부정하는 동물","original":"Denial of Animality","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"동물 캐릭터가 자신이 동물이라는 사실을 모르거나 인정하지 않고 사람이라고 주장하는 설정. 정체성과 겉모습의 차이가 웃음이나 갈등을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-007057/index.html"},{"id":"MEJE-KW-007058","row_version":2,"title":"대각선 공격이 불가능한 게임","original":"Denial of Diagonal Attack","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 캐릭터의 공격 방향이 좌우 등으로 제한되어 비스듬한 위치의 대상을 곧바로 맞힐 수 없는 조작 규칙. 화면의 단순한 위치 차이가 플레이의 장애물이 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-007058/index.html"},{"id":"MEJE-KW-007059","row_version":1,"title":"디지털판 없는 발매","original":"Denial of Digital Distribution","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품을 물리 매체로만 내고 다운로드나 스트리밍 유통을 제공하지 않는 발매 방식. 권리 문제나 창작자의 선택 등으로 접근 경로가 제한된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007059/index.html"},{"id":"MEJE-KW-007060","row_version":1,"title":"닮았다는 말을 부정하는 인물","original":"Denial of Resemblance","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"두 사람이 닮았다는 지적을 한쪽이 당황하거나 화를 내며 부인하는 장면. 관객이 보는 외모와 인물의 자기 인식 사이에 간극이 생긴다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007060/index.html"},{"id":"MEJE-KW-007061","row_version":1,"title":"식사를 빼앗는 벌","original":"Denied Food as Punishment","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"권한을 가진 인물이 불복종이나 잘못을 이유로 상대의 식사를 금지하는 처벌 장면. 음식에 대한 통제가 두 사람 사이의 권력 차이를 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007061/index.html"},{"id":"MEJE-KW-007062","row_version":1,"title":"풍자 대상을 부정하는 창작자","original":"Denied Parody","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 인물이나 조직이 현실의 특정 대상을 뚜렷이 떠올리게 하는데도 창작자가 이를 풍자가 아니라고 주장하는 상황. 표현과 해명 사이의 차이가 논쟁을 만든다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007062/index.html"},{"id":"MEJE-KW-007063","row_version":1,"title":"혼자 있을 시간을 빼앗긴 인물","original":"Denied Their Alone Time","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"혼자 있으려는 인물의 의사와 달리 다른 사람들이 계속 찾아오거나 간섭하는 전개. 사생활의 필요와 주변의 기대가 부딪힌다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007063/index.html"},{"id":"MEJE-KW-007064","row_version":1,"title":"향락과 범죄의 소굴","original":"Den of Iniquity","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"악역의 근거지 안팎에 각종 방탕한 일이나 범죄가 벌어지는 장소를 두는 설정. 공간의 성격으로 집단의 도덕적 이미지를 드러낸다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-007064/index.html"},{"id":"MEJE-KW-007065","row_version":2,"title":"점점 과장되는 후속 시즌","original":"Denser and Wackier","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"연재가 이어질수록 사건과 인물의 행동이 처음보다 더 소란스럽고 만화적으로 바뀌는 톤 변화. 같은 시리즈의 분위기가 점차 달라진다. 시리즈의 분위기가 변하면서 이전 주요 인물의 비중까지 줄면 주연에서 단역으로 밀린 인물도 함께 일어난다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007065/index.html"},{"id":"MEJE-KW-007066","row_version":2,"title":"상처가 쌓이는 강인한 인물","original":"Dented Iron","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"평소에는 공격을 버티는 인물도 거듭된 부상 뒤에는 지치고 몸이 무너지는 모습으로 그려진다. 강함에도 한계가 있음을 보여 준다. 거듭된 상처 끝에 궁지에 몰린 인물이 다시 맞서면 궁지에서 터지는 마지막 반격의 장면으로 이어진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007066/index.html"},{"id":"MEJE-KW-007067","row_version":1,"title":"죽은 부모의 잘못을 부정하기","original":"Denying the Dead Parent's Sins","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"존경하던 부모의 숨겨진 잘못을 알게 된 인물이 처음에는 믿지 않으려는 반응. 기억 속 부모상과 새 증거가 충돌한다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007067/index.html"},{"id":"MEJE-KW-007068","row_version":1,"title":"제 역할을 못 하는 아동 보호 기관","original":"Department of Child Disservices","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"작품 속 아동 보호 기관이 도움이 필요한 아이를 놓치거나 적절한 가정을 부당하게 막는 등 본래 임무에 실패하는 묘사. 제도의 무능이 갈등의 원인이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-007068/index.html"},{"id":"MEJE-KW-007069","row_version":1,"title":"불친절한 관공서","original":"Department of Major Vexation","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물이 공공 업무를 처리하려 할 때 복잡한 절차와 무성의한 직원 때문에 진척하지 못하는 장면. 행정 공간이 일상의 장애물로 쓰인다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-007069/index.html"},{"id":"MEJE-KW-007070","row_version":1,"title":"말의 중복을 겹쳐 쓰기","original":"Department of Redundancy Department","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"같은 뜻의 말이나 항목을 불필요하게 되풀이하는 언어적 농담. 되풀이 자체가 말의 어색함을 드러내며, 약어의 풀이나 표현 속에도 나타난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007070/index.html"},{"id":"MEJE-KW-007071","row_version":1,"title":"고향을 떠나면 죽는 존재","original":"Departure Means Death","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"어떤 존재가 자신이 속한 세계나 장소를 벗어나면 생존할 수 없다는 규칙. 여행과 이별을 생명의 문제로 만든다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-007071/index.html"},{"id":"MEJE-KW-007072","row_version":2,"title":"작화가마다 다른 외모","original":"Depending on the Artist","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"여러 화가가 같은 인물을 그릴 때 얼굴이나 몸의 모습이 작품마다 다르게 나타나는 현상. 공동 창작과 매체 이동 속에서 시각적 정체성이 흔들린다. 공동 창작에서 외형뿐 아니라 성격도 달라지면 작가마다 다른 성격의 변화까지 생긴다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007072/index.html"},{"id":"MEJE-KW-007073","row_version":2,"title":"작가마다 다른 성격","original":"Depending on the Writer","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"여러 작가가 같은 인물을 맡으면서 성격과 신념, 말투가 작품마다 눈에 띄게 달라지는 현상. 인물 설정의 연속성에 대한 관객의 기대와 어긋난다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007073/index.html"},{"id":"MEJE-KW-007074","row_version":1,"title":"무능함을 알면서 맡기는 중요한 일","original":"Depending Upon the Undependable","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"주변 사람들이 어떤 인물의 심각한 실수 가능성을 알면서도 중요한 임무를 계속 맡기는 전개. 반복되는 실패만큼 맡기는 사람들의 판단도 문제로 드러난다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007074/index.html"},{"id":"MEJE-KW-007075","row_version":1,"title":"적의 약점을 담은 탄약","original":"Depleted Phlebotinum Shells","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"특정 적에게만 통하는 성분이나 효과를 탄약에 담아 보통 무기의 한계를 넘는 허구적 장비. 무기 자체보다 담긴 물질의 성질이 승부를 가른다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-007075/index.html"},{"id":"MEJE-KW-007076","row_version":1,"title":"설치할 수 있는 엄폐물","original":"Deployable Cover","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 인물이 필요할 때 보호벽이나 방패 같은 엄폐 공간을 만들어 배치하는 기능. 고정된 지형 외에도 방어 위치를 새로 정할 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-007076/index.html"},{"id":"MEJE-KW-007077","row_version":1,"title":"인구를 급감시키는 재앙 장치","original":"Depopulation Bomb","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"이야기에서 광범위한 인구 감소를 일으키는 무기나 재난을 핵심 사건으로 두는 장치. 사회의 붕괴와 살아남은 이들의 세계를 여는 계기가 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007077/index.html"},{"id":"MEJE-KW-007078","row_version":2,"title":"초능력 상실","original":"De-power","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"강한 능력을 가진 인물이 오랫동안 또는 영구적으로 그 힘을 잃는 전개. 이전에 능력으로 해결하던 문제를 다른 방식으로 마주하게 된다. 능력을 잃는 원인이 특정 장소의 규칙이라면 능력이 사라지는 구역과 이어진다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-007078/index.html"},{"id":"MEJE-KW-007079","row_version":2,"title":"능력이 사라지는 구역","original":"De-Power Zone","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"초능력자가 들어가면 일부 또는 모든 능력을 쓰지 못하게 되는 장소의 설정. 공간의 규칙이 강한 인물에게 새로운 제약을 건다. 일시적인 공간 효과가 되돌릴 수 없는 결과로 굳어지면 초능력 상실이 된다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-007079/index.html"},{"id":"MEJE-KW-007080","row_version":2,"title":"양성애를 악역성과 묶는 편견","original":"Depraved Bisexual","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"양성애 인물을 잔혹하거나 위험한 악역으로 반복 묘사해 성적 지향과 비도덕성을 연결하는 표현 관습. 인물의 악행을 정체성의 속성처럼 보이게 할 수 있는 고정관념이다. 성적 지향을 악행의 이유처럼 보이게 하는 편향이라는 점에서 동성애를 악역성과 묶는 편견과 함께 검토할 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007080/index.html"},{"id":"MEJE-KW-007081","row_version":1,"title":"가학적인 치과의사 고정관념","original":"Depraved Dentist","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"치과 치료에 대한 두려움을 이용해 치과의사를 고통을 즐기는 악역으로 그리는 인물형. 직업에 대한 불안을 과장한 허구적 묘사이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007081/index.html"},{"id":"MEJE-KW-007082","row_version":1,"title":"저신장을 악역성과 묶는 편견","original":"Depraved Dwarf","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"키가 작은 인물을 성적으로 비정상적이거나 사악한 사람으로 그리는 낡은 묘사 관습. 신체 특성과 도덕성을 부당하게 연결하는 고정관념이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007082/index.html"},{"id":"MEJE-KW-007083","row_version":1,"title":"동성애를 악역성과 묶는 편견","original":"Depraved Homosexual","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"동성애 인물을 위협적이고 포식적인 악역으로 반복 그리는 표현 관습. 성적 지향 자체가 위험성의 근거라는 잘못된 인상을 만들 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007083/index.html"},{"id":"MEJE-KW-007084","row_version":1,"title":"방송 밖에서 다른 어린이 프로그램 진행자","original":"Depraved Kids' Show Host","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"방송에서는 아이들에게 친절하지만 사생활에서는 무책임하거나 위험한 어린이 프로그램 진행자 인물형. 화면의 선한 이미지와 실제 행동이 대비된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007084/index.html"},{"id":"MEJE-KW-007085","row_version":1,"title":"우울을 다루는 교훈","original":"Depression Aesop","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품이 우울의 경험과 회복 가능성에 대해 인물이나 관객에게 전하려는 메시지. 복잡한 상태를 단순한 의지 문제로 축소하지 않는 묘사가 중요하다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-007085/index.html"},{"id":"MEJE-KW-007086","row_version":1,"title":"세뇌에서 벗어나게 하기","original":"Deprogram","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"조종이나 세뇌를 겪은 인물이 이전의 판단과 기억을 되찾도록 돕는 이야기의 과정. 외부 통제에서 벗어나 자기 결정권을 회복하는 데 초점을 둔다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007086/index.html"},{"id":"MEJE-KW-007087","row_version":3,"title":"원근감 때문에 생긴 착각","original":"Depth Deception","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"카메라나 관찰자의 위치 탓에 가까운 작은 물체를 멀리 있는 큰 물체로 오인하는 시각 효과. 실제 거리와 화면에서 읽히는 크기의 차이를 이용한다. 거리와 크기를 잘못 읽는 문제가 게임의 화면 판정으로 옮겨 가면 게임 화면의 깊이 혼란이 된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007087/index.html"},{"id":"MEJE-KW-007088","row_version":1,"title":"피사계 심도","original":"Depth of Field","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"영상이나 사진에서 초점이 맞아 선명하게 보이는 거리의 범위. 범위를 좁히거나 넓혀 관객이 보아야 할 대상과 공간감을 조절한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007088/index.html"},{"id":"MEJE-KW-007089","row_version":2,"title":"게임 화면의 깊이 혼란","original":"Depth Perplexion","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 배경과 전경, 캐릭터 층이 제대로 구분되지 않아 물체 사이의 거리나 충돌 관계를 알기 어려운 문제. 화면에서 보이는 위치와 실제 판정이 어긋난다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-007089/index.html"},{"id":"MEJE-KW-007090","row_version":2,"title":"이야기하다 탈선한 동화","original":"Derailed Fairy Tale","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품 속 화자가 익숙한 동화를 들려주다가 듣는 사람의 요구나 자신의 변형을 계속 받아 이야기가 엉뚱한 방향으로 흘러가는 장면. 원래 이야기의 질서가 무너지는 과정이 볼거리다. 듣는 사람이 세부 사항을 계속 캐물어 동화가 무너지면 사소한 질문에 끊기는 이야기이 원인이 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007090/index.html"},{"id":"MEJE-KW-007091","row_version":2,"title":"사소한 질문에 끊기는 이야기","original":"Derailed for Details","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"누군가 이야기를 하려는데 듣는 사람이 중요하지 않은 세부 사항을 계속 캐물어 본론을 잃는 대화 장면. 설명을 다듬으려는 시도가 오히려 진행을 막는다. 질문에 답하던 화자도 연상된 이야기로 빠져들면 옆길로 새는 생각이 겹친다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007091/index.html"},{"id":"MEJE-KW-007092","row_version":1,"title":"옆길로 새는 생각","original":"Derailed Train of Thought","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"한 주제를 말하던 인물이 연상되는 다른 이야기로 계속 옮겨 가 처음의 화제를 잊는 대화 습관. 사고의 흐름이 말의 방향을 바꾼다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-007092/index.html"},{"id":"MEJE-KW-007093","row_version":2,"title":"연애 경쟁자를 억지로 망가뜨리기","original":"Derailing Love Interests","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 특정 연인 관계를 성립시키려고 경쟁 상대의 성격이나 행동을 갑자기 나쁘게 바꾸는 구성. 관계의 설득력보다 원하는 결말을 앞세운 흔적이 보인다. 경쟁 상대를 갑자기 나쁘게 만들어도 새로 밀어 준 관계가 설득되지 않으면 관계가 보이지 않는 공식 연인가 남는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007093/index.html"},{"id":"MEJE-KW-007094","row_version":2,"title":"현실 감각을 벗어난 애니메이션","original":"Deranged Animation","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"애니메이션의 자유로운 표현을 이용해 형태와 사건의 논리가 불안정하게 바뀌는 기괴한 영상 스타일. 현실을 벗어난 움직임이 웃음이나 불안을 만든다. 영상 전체의 기괴한 움직임을 한 인물의 춤으로 집중하면 불안정한 마음을 드러내는 춤이 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-007094/index.html"},{"id":"MEJE-KW-007095","row_version":1,"title":"불안정한 마음을 드러내는 춤","original":"Deranged Dance","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"인물이 뒤틀리거나 불규칙한 춤으로 심리적 혼란을 표현하는 연출. 몸짓이 말보다 직접적으로 인물의 위태로운 상태를 보여 준다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-007095/index.html"},{"id":"MEJE-KW-007096","row_version":2,"title":"위험한 공원 관리인","original":"Deranged Park Ranger","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"방문객과 자연을 지켜야 할 공원 관리인이 오히려 위협적인 인물로 나타나는 설정. 안전을 맡은 직책에 대한 기대를 뒤집는다. 안전을 맡은 직업인이 오히려 위협이 되는 반전은 위험한 택시 운전사에도 쓰인다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007096/index.html"},{"id":"MEJE-KW-007097","row_version":1,"title":"위험한 택시 운전사","original":"Deranged Taxi Driver","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"승객을 목적지로 데려가야 할 운전사가 엉뚱하거나 위협적인 행동으로 이동 자체를 위험하게 만드는 인물형. 밀폐된 차 안의 권력 차이가 긴장을 높인다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-007097/index.html"},{"id":"MEJE-KW-007098","row_version":2,"title":"방치된 탈것의 무덤","original":"Derelict Graveyard","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"버려진 배나 비행기, 우주선이 한곳에 여럿 모여 있는 장소. 과거의 이동과 실패가 잔해의 풍경으로 남는다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-007098/index.html"},{"id":"MEJE-KW-007099","row_version":2,"title":"모방작의 차별화","original":"Derivative Differentiation","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"기존 성공작을 닮은 작품이 시간이 지나며 고유한 인물과 설정, 표현을 키워 다른 정체성을 얻는 변화. 출발점의 유사성과 이후의 독자성을 함께 볼 수 있다. 원본의 환상 요소를 걷어 내는 방식으로 독자성을 찾는 경우 신화의 현실적 재해석을 선택한 셈이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007099/index.html"},{"id":"MEJE-KW-007100","row_version":1,"title":"제작진의 일반 배역 출연","original":"Descended Creator","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품 제작자나 제작진이 카메오를 넘어 원래 배우가 맡을 만한 배역으로 출연하는 경우. 창작 현장의 사람이 작품 안의 인물이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-007100/index.html"},{"id":"MEJE-KW-007101","row_version":3,"title":"전면에 나선 배후의 최종 적","original":"Descended Greater-Scope Villain","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"뒤에서 영향력을 행사하던 더 큰 악역이 기존 주요 악역이 물러난 뒤 직접 주인공과 맞서는 전개. 이전 사건의 배후가 새 갈등의 중심으로 옮겨 온다. 기존 악역 뒤에 더 큰 적을 내세우는 대신 비슷한 외형의 후임을 들이면 옛 악역의 외형을 잇는 새 악역이 된다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-007101/index.html"},{"id":"MEJE-KW-007102","row_version":1,"title":"내려오는 천장 함정","original":"Descending Ceiling","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"공간의 천장이 점차 내려와 안에 있는 인물에게 위협을 주는 허구의 함정. 좁아지는 여유 공간이 시간 압박을 눈에 보이게 한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-007102/index.html"},{"id":"MEJE-KW-007103","row_version":3,"title":"중독으로 기울어지는 인물","original":"Descent into Addiction","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 물질이나 행동에 대한 의존을 키우며 삶과 관계가 무너지는 과정을 따라가는 서사. 단일한 사건보다 변화의 누적이 핵심이다. 인물의 의존이 깊어지는 변화를 노래의 분위기로 표현하면 점점 어두워지는 노래과 연결된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-007103/index.html"},{"id":"MEJE-KW-007104","row_version":1,"title":"점점 어두워지는 노래","original":"Descent into Darkness Song","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"밝게 시작한 노래가 진행될수록 가사나 분위기에서 불길한 방향으로 바뀌는 음악 연출. 선율의 변화가 인물이나 사건의 전환을 전한다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-007104/index.html"},{"id":"MEJE-KW-007105","row_version":1,"title":"설명과 반대 모습의 즉시 제시","original":"Description Cut","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이나 상황을 말로 설명한 직후 실제 모습이 정반대로 나타나는 연출. 같은 대화 안이나 이어지는 장면에서 말과 현실의 충돌이 웃음을 만든다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-007105/index.html"},{"id":"MEJE-KW-007106","row_version":2,"title":"거울로 자기 외모 소개하기","original":"Description in the Mirror","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"시점 인물의 외모를 설명하기 위해 그 인물이 거울을 들여다보게 하는 서술 장치. 스스로 볼 수 없는 얼굴을 자연스럽게 묘사하려는 구성이다. 거울에 비친 모습을 필요 이상으로 길게 설명하면 감정을 부르는 장황한 사물 설명의 방식이 겹친다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007106/index.html"},{"id":"MEJE-KW-007107","row_version":1,"title":"감정을 부르는 장황한 사물 설명","original":"Description Porn","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"사물의 이름과 수치, 특징을 길게 늘어놓아 경외감이나 두려움을 끌어내는 설명 방식. 정보의 양과 세부 묘사가 대상의 존재감을 부풀린다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-007107/index.html"},{"id":"MEJE-KW-007108","row_version":1,"title":"기능을 그대로 말하는 지명","original":"Descriptiveville","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"허구의 장소 이름이 그곳의 주민이나 용도, 지형을 곧바로 설명하는 작명 관습. 이해하기 쉽지만 세계가 실제로 쌓아 온 역사감은 옅어질 수 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-007108/index.html"},{"id":"MEJE-KW-007109","row_version":1,"title":"고인의 몸을 모욕하기","original":"Desecrating the Dead","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물의 사망 뒤 남은 몸을 훼손하거나 공개적으로 모욕하는 사건. 죽은 사람과 그를 기억하는 이들에게 적대감을 드러내는 묘사이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-007109/index.html"},{"id":"MEJE-KW-007110","row_version":2,"title":"사막의 약탈자 고정관념","original":"Desert Bandits","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"사막에 사는 사람들을 생존을 위해 여행자를 습격하는 집단으로 단순화해 그리는 허구의 관습. 지역과 주민을 한 가지 위협 이미지로 묶는 편향을 살펴볼 수 있다. 사막 주민을 하나의 인물상으로 고정한다는 점에서 사막 주민의 환경 적응력의 표현과 함께 살펴볼 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007110/index.html"},{"id":"MEJE-KW-007111","row_version":2,"title":"무인도 표류 배경","original":"Deserted Island","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"사람이 살지 않는 섬에 인물이 남겨져 한정된 자원과 구조의 불확실성을 마주하는 배경. 고립된 공간이 생존과 관계의 조건을 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-007111/index.html"},{"id":"MEJE-KW-007112","row_version":1,"title":"사막 주민의 환경 적응력","original":"Desert People","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 사막 지역 주민을 외부인보다 지형과 기후를 잘 아는 집단으로 묘사하는 관습. 실제 문화의 다양성을 지우는 단일한 이미지로 쓰이지 않도록 구분해 볼 필요가 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-007112/index.html"},{"id":"MEJE-KW-007113","row_version":3,"title":"사막 행성 중심의 과학소설","original":"Desert Punk","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"건조한 행성이나 광대한 사막을 주된 무대로 삼아 자원과 생존, 이동의 문제를 다루는 과학소설 배경. 척박한 환경이 사회와 기술의 모습을 규정한다. 사막 행성의 황량함을 짧은 시각 기호로 전하려 할 때 사막의 해골 이미지를 사용할 수 있다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-007113/index.html"},{"id":"MEJE-KW-007114","row_version":1,"title":"사막의 해골 이미지","original":"Desert Skull","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"사막이나 메마른 땅을 보여 줄 때 동물의 두개골을 놓아 황량함을 알리는 시각 관습. 짧은 화면만으로 생명의 흔적이 적은 공간이라는 인상을 준다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-007114/index.html"},{"id":"MEJE-KW-007115","row_version":1,"title":"사막을 배경으로 한 전투","original":"Desert Warfare","aliases":[],"kind":"keyword","facet_id":"ML-F08","node_kind":null,"parent_id":null,"tag_path":["ML-F08"],"summary":"전쟁이나 대결이 사막에서 벌어져 뜨거운 기후와 부족한 자원이 갈등의 조건이 되는 장면. 환경 자체도 맞서야 할 난관으로 그려진다.","accent":"#936E72","tab":"#9A6A55","facet":"갈등·장애","bookmark":"분류축","entry_url":"cards/MEJE-KW-007115/index.html"}]}.cards;